"""Bahasa Indonesia — tingkat pemula (200 pertanyaan)."""

T = {
"prophets_251": ("Siapakah nama Nabi umat Islam?", ["Muhammad ﷺ", "Ibrahim", "Musa", "Isa"], "Nabi umat Islam adalah Muhammad ﷺ, putra Abdullah."),
"prophets_252": ("Isma'il dan Ishaq adalah putra nabi siapakah?", ["Ibrahim", "Musa", "Nuh", "Dawud"], "«Segala puji bagi Allah yang telah menganugerahkan kepadaku di hari tuaku Isma'il dan Ishaq» (14:39)."),
"prophets_253": ("Nabi siapakah yang diangkat Allah kepada-Nya?", ["Isa", "Yunus", "Ayyub", "Idris"], "«Tetapi Allah telah mengangkatnya kepada-Nya» (4:158)."),
"prophets_254": ("Siapakah ibu Nabi Isa?", ["Maryam", "Asiyah", "Hajar", "Sara"], "Maryam, yang namanya menjadi nama satu surah penuh dalam Al-Qur'an."),
"prophets_255": ("Siapakah manusia pertama yang diciptakan Allah?", ["Adam", "Nuh", "Ibrahim", "Idris"], "Adam adalah manusia pertama, yang diajari Allah semua nama."),
"prophets_256": ("Bagi nabi siapakah api menjadi dingin dan selamat?", ["Ibrahim", "Musa", "Yusuf", "Sulaiman"], "«Wahai api, jadilah dingin dan selamat bagi Ibrahim.»"),
"prophets_257": ("Nabi siapakah yang membawa tongkat yang berubah menjadi ular?", ["Musa", "Harun", "Yahya", "Zakariyya"], "Allah bertanya kepada Musa: «Apakah yang ada di tangan kananmu itu?»"),
"prophets_258": ("Nabi siapakah yang bermimpi melihat sebelas bintang bersujud?", ["Yusuf", "Ya'qub", "Ishaq", "Dawud"], "«Wahai ayahku, aku melihat sebelas bintang, matahari dan bulan.»"),
"prophets_259": ("Burung apakah yang membawa kabar kepada Nabi Sulaiman?", ["Burung hud-hud", "Burung gagak", "Burung elang", "Burung merpati"], "Hud-hud berkata: «Aku datang kepadamu dari negeri Saba dengan membawa kabar yang meyakinkan» (27:22)."),
"prophets_260": ("Nabi siapakah yang menjadi teladan kesabaran dalam ujian?", ["Ayyub", "Yunus", "Lut", "Syu'aib"], "Ayyub berdoa kepada Tuhannya dan terbukti sangat sabar."),
"prophets_261": ("Dari apakah Allah menciptakan Adam?", ["Dari tanah", "Dari cahaya", "Dari api", "Dari angin"], "«Dia menciptakannya dari tanah, kemudian berfirman kepadanya: Jadilah!» (3:59)."),
"prophets_262": ("Nabi siapakah yang diajak bicara langsung oleh Allah?", ["Musa", "Yusuf", "Yunus", "Salih"], "«Dan Allah telah berbicara kepada Musa secara langsung.»"),
"prophets_263": ("Berapa jumlah nabi yang datang setelah Muhammad ﷺ?", ["Tidak ada: dia adalah nabi terakhir", "Satu", "Tiga", "Tujuh"], "Muhammad ﷺ adalah penutup para nabi: tidak ada nabi lagi setelahnya."),
"prophets_264": ("Nabi siapakah yang disebut kekasih (khalil) Allah?", ["Ibrahim", "Musa", "Isa", "Nuh"], "Ibrahim adalah bapak para nabi dan kekasih Yang Maha Pengasih."),
"prophets_265": ("Nabi siapakah yang menyembuhkan orang buta sejak lahir dengan izin Allah?", ["Isa", "Yahya", "Zakariyya", "Ilyas"], "«Dan engkau menyembuhkan orang yang buta sejak lahir dan orang yang berpenyakit kusta dengan izin-Ku.»"),
"prophets_266": ("Bagi nabi siapakah gunung-gunung ikut bertasbih memuji Allah?", ["Dawud", "Sulaiman", "Ayyub", "Yunus"], "«Wahai gunung-gunung, bertasbihlah berulang-ulang bersama dia.»"),
"prophets_267": ("Nabi siapakah yang menjelaskan mimpi raja Mesir?", ["Yusuf", "Harun", "Ilyas", "Syu'aib"], "Yusuf menjelaskan mimpi tujuh sapi gemuk dan tujuh sapi kurus (12:46-49)."),
"prophets_268": ("Siapakah ayah Nabi Yusuf?", ["Ya'qub", "Ishaq", "Ibrahim", "Lut"], "Yusuf adalah putra Ya'qub, dan Ya'qub adalah putra Ishaq."),
"prophets_269": ("Apakah yang terbelah di hadapan Musa dan kaumnya?", ["Laut, yang terbelah untuk menyelamatkan mereka dari Fir'aun", "Sebuah sungai di Mesir", "Sebuah danau di Madyan", "Sebuah sumur di gurun"], "«Dan ketika Kami membelah laut untukmu, lalu Kami selamatkan kamu.»"),
"prophets_270": ("Apa yang diucapkan setelah menyebut nama Nabi ﷺ?", ["«Semoga Allah melimpahkan selawat dan salam kepadanya»", "Tidak ada yang khusus", "«Terima kasih»", "«Selamat tinggal»"], "Kita bersalawat dan mengucapkan salam kepadanya: shallallahu 'alaihi wa sallam."),
"prophets_271": ("Nabi siapakah yang berdakwah kepada kaumnya sangat lama sebelum banjir besar?", ["Nuh", "Hud", "Salih", "Syu'aib"], "«Kami mengutus Nuh kepada kaumnya: berilah peringatan kepada kaummu.»"),
"prophets_272": ("Sulaiman adalah putra nabi siapakah?", ["Dawud", "Ya'qub", "Ishaq", "Yunus"], "«Dan Kami karuniakan kepada Dawud, Sulaiman — sebaik-baik hamba!» (38:30)."),
"prophets_273": ("Nabi siapakah yang mengalahkan Jalut (Goliat)?", ["Dawud", "Sulaiman", "Yusya'", "Ilyas"], "«Dan Dawud membunuh Jalut» (2:251)."),
"prophets_274": ("Berapa jumlah nabi yang wajib diimani seorang Muslim?", ["Semuanya, tanpa membeda-bedakan", "Hanya nabi terakhir", "Hanya tiga", "Hanya yang disebut dalam Al-Qur'an"], "Seorang Muslim beriman kepada semua nabi Allah, tanpa membeda-bedakan seorang pun di antara mereka."),
"prophets_275": ("Siapakah yang dipilih Allah, menurut Al-Qur'an?", ["Adam, Nuh, keluarga Ibrahim dan keluarga 'Imran", "Raja-raja Mesir", "Suku-suku Madinah", "Penduduk Saba"], "«Allah telah memilih Adam, Nuh, keluarga Ibrahim dan keluarga 'Imran.»"),
"prophets_276": ("Di negeri manakah Nabi Yusuf menjadi orang kepercayaan raja?", ["Mesir", "Syam", "Yaman", "Irak"], "Yusuf mendapat kedudukan di Mesir setelah menafsirkan mimpi raja."),
"prophets_277": ("Nabi siapakah yang diperjalankan pada malam hari ke Masjidil Aqsa?", ["Muhammad ﷺ", "Musa", "Isa", "Ibrahim"], "«Mahasuci Allah yang telah memperjalankan hamba-Nya pada malam hari.»"),
"prophets_278": ("Kitab apakah yang diberikan kepada Nabi Musa?", ["Taurat", "Injil", "Zabur", "Suhuf Ibrahim"], "Allah memberi Musa Kitab dan mengutus rasul-rasul setelahnya."),
"prophets_279": ("Kitab apakah yang diberikan kepada Nabi Isa?", ["Injil", "Taurat", "Zabur", "Al-Qur'an"], "«Dan Kami memberinya Injil, di dalamnya ada petunjuk dan cahaya.»"),
"prophets_280": ("Kitab apakah yang diberikan kepada Nabi Dawud?", ["Zabur", "Taurat", "Injil", "Suhuf Musa"], "«Dan Kami berikan Zabur kepada Dawud.»"),
"prophets_281": ("Putra nabi siapakah yang rela dikurbankan demi taat kepada Allah?", ["Putra Ibrahim", "Putra Nuh", "Saudara Musa", "Putra Ya'qub"], "«Wahai ayahku, lakukanlah apa yang diperintahkan kepadamu: engkau akan mendapatiku termasuk orang yang sabar.»"),
"prophets_282": ("Di manakah ibu Musa meletakkan bayinya agar selamat?", ["Di sungai", "Di dalam gua", "Di rumah tetangga", "Di gurun"], "«Hanyutkanlah dia ke sungai: Kami akan mengembalikannya kepadamu.»"),
"prophets_283": ("Apa yang diucapkan Yunus dalam kegelapan, yang diulang setiap Muslim?", ["«Tidak ada tuhan selain Engkau, Mahasuci Engkau, sungguh aku termasuk orang yang zalim»", "«Berilah aku kekayaan»", "«Jadikanlah aku raja»", "«Jadikanlah aku kuat»"], "Inilah doa Yunus di dalam perut ikan."),
"prophets_284": ("Siapakah ayah Nabi Muhammad ﷺ?", ["Abdullah", "Abu Thalib", "Al-Abbas", "Hamzah"], "Beliau adalah Muhammad ﷺ, putra Abdullah, putra Abdul Muthalib."),
"prophets_285": ("Siapakah ibu Nabi Muhammad ﷺ?", ["Aminah", "Khadijah", "Aisyah", "Fathimah"], "Aminah binti Wahb adalah ibu Nabi ﷺ."),
"prophets_286": ("Apa yang dikatakan Isa saat masih dalam buaian?", ["«Aku adalah hamba Allah»", "«Aku adalah raja»", "«Aku adalah malaikat»", "Ia tidak berkata apa-apa"], "«Sesungguhnya aku hamba Allah: Dia memberiku Kitab.»"),
"prophets_287": ("Nabi siapakah yang diutus kepada kaum 'Ad?", ["Hud", "Salih", "Lut", "Syu'aib"], "«Dan kepada kaum 'Ad, saudara mereka Hud.»"),
"prophets_288": ("Nabi siapakah yang diutus kepada kaum Tsamud, dengan unta betina?", ["Salih", "Hud", "Yunus", "Idris"], "«Dan kepada kaum Tsamud, saudara mereka Salih: inilah unta betina Allah.»"),
"prophets_289": ("Nabi siapakah yang menjadi saudara Musa dan diutus bersamanya?", ["Harun", "Yusuf", "Yahya", "Ilyas"], "«Dan jadikanlah untukku seorang pembantu dari keluargaku: Harun, saudaraku.»"),
"prophets_290": ("Gelar apakah yang diberikan Al-Qur'an kepada Muhammad ﷺ di antara para nabi?", ["Penutup para nabi", "Nabi yang pertama", "Raja para nabi", "Juru tulis para nabi"], "«Muhammad adalah utusan Allah dan penutup para nabi.»"),
"prophets_291": ("Apa yang dikatakan para malaikat kepada Maryam dalam Al-Qur'an?", ["Bahwa Allah telah memilih dan menyucikannya", "Bahwa ia akan menjadi ratu", "Bahwa ia akan bepergian", "Bahwa ia akan mengajar"], "«Wahai Maryam, sesungguhnya Allah telah memilihmu dan menyucikanmu.»"),
"prophets_292": ("Bagaimana Ayyub berdoa kepada Tuhannya dalam ujiannya?", ["«Aku telah ditimpa penyakit, dan Engkau Maha Penyayang»", "«Jadikanlah aku kaya»", "«Hukumlah musuh-musuhku»", "«Jadikanlah aku raja»"], "«Aku telah ditimpa penyakit, dan Engkaulah Yang Maha Penyayang di antara semua penyayang.»"),
"prophets_293": ("Apa yang diajarkan Allah kepada Adam?", ["Semua nama", "Menulis", "Berlayar", "Berhitung"], "«Dan Dia mengajarkan kepada Adam nama-nama semuanya.»"),
"prophets_294": ("Nabi siapakah yang memerintah kerajaan yang tidak akan dimiliki siapa pun setelahnya?", ["Sulaiman", "Dawud", "Yusuf", "Dzulqarnain"], "«Anugerahkanlah kepadaku kerajaan yang tidak dimiliki oleh siapa pun setelahku.»"),
"prophets_295": ("Nabi siapakah yang diselamatkan bersama keluarganya, kecuali istrinya?", ["Lut", "Nuh", "Hud", "Salih"], "«Pergilah bersama keluargamu pada akhir malam… kecuali istrimu.»"),
"prophets_296": ("Dari apakah Ibrahim memperingatkan kaumnya?", ["Menyembah berhala", "Berdagang", "Bepergian", "Menulis"], "«Pantaskah engkau menjadikan berhala-berhala itu sebagai tuhan?»"),
"prophets_297": ("Kata apakah yang berarti orang yang diutus Allah kepada manusia?", ["Seorang utusan (rasul)", "Seorang khalifah", "Seorang sahabat", "Seorang ulama"], "Rasul adalah orang yang diutus Allah, yang dipercaya membawa pesan bagi manusia."),
"prophets_298": ("Sebagai apakah Allah mengutus Nabi ﷺ, menurut surah Al-Ahzab?", ["Saksi, pembawa kabar gembira dan pemberi peringatan", "Raja dan hakim", "Pedagang", "Penyair"], "«Wahai Nabi, sesungguhnya Kami mengutusmu sebagai saksi, pembawa kabar gembira dan pemberi peringatan» (33:45)."),
"prophets_299": ("Mengapa Muhammad ﷺ diutus, menurut Al-Qur'an?", ["Sebagai rahmat bagi seluruh alam", "Untuk memerintah", "Untuk membangun", "Untuk berdagang"], "«Dan Kami tidak mengutusmu melainkan sebagai rahmat bagi seluruh alam.»"),
"prophets_300": ("Nabi siapakah yang disebut Al-Qur'an «hamba yang banyak bersyukur»?", ["Nuh", "Lut", "Idris", "Ilyas"], "«Sesungguhnya dia adalah hamba yang banyak bersyukur» (17:3), dikatakan tentang Nuh."),
"prophets_301": ("Tanda apakah yang diberikan kepada Zakariyya setelah kabar gembira tentang putranya?", ["Tidak berbicara kepada manusia selama tiga hari", "Melihat sebuah bintang", "Mendengar guntur", "Berjalan di atas air"], "«Tandamu adalah engkau tidak berbicara kepada manusia selama tiga hari» (3:41)."),
"prophets_302": ("Dengan bahasa apakah setiap rasul diutus?", ["Dengan bahasa kaumnya sendiri", "Hanya dengan bahasa Arab", "Dengan bahasa Ibrani", "Dengan bahasa langit"], "«Kami tidak mengutus seorang rasul pun melainkan dengan bahasa kaumnya.»"),
"prophets_303": ("Surah manakah yang menceritakan kisah seorang nabi dari awal sampai akhir?", ["Surah Yusuf", "Surah Al-Baqarah", "Surah An-Nas", "Surah Al-Fatihah"], "«Kami menceritakan kepadamu kisah yang paling baik» — kisah Yusuf."),
"prophets_304": ("Bagaimana Al-Qur'an menggambarkan Ibrahim dalam surah Maryam?", ["Seorang yang sangat benar, seorang nabi", "Seorang raja", "Seorang juru tulis", "Seorang pedagang"], "«Sesungguhnya dia adalah seorang yang sangat benar, seorang nabi.»"),
"prophets_305": ("Ratu manakah yang datang menemui Nabi Sulaiman?", ["Ratu Saba", "Ratu Mesir", "Ratu Babilonia", "Ratu Yaman utara"], "Ia berserah diri bersama Sulaiman kepada Allah, Tuhan seluruh alam."),
"prophets_306": ("Nabi siapakah yang meminta diperlihatkan bagaimana Allah menghidupkan kembali?", ["Ibrahim", "Musa", "Nuh", "Yunus"], "«Ya Tuhanku, perlihatkanlah kepadaku bagaimana Engkau menghidupkan orang mati.»"),
"prophets_307": ("Nabi siapakah yang melakukan perjalanan untuk belajar dari seorang hamba yang berilmu?", ["Musa", "Yusuf", "Dawud", "Sulaiman"], "Musa berjalan hingga bertemu seorang hamba Allah yang telah diberi-Nya ilmu."),
"prophets_308": ("Apa yang diajarkan surah Al-Ikhlas tentang Allah?", ["Bahwa Dia Maha Esa, dan tidak ada yang setara dengan-Nya", "Bahwa Dia memiliki sekutu", "Bahwa Dia menyerupai makhluk-Nya", "Bahwa Dia memiliki anak"], "«Katakanlah: Dialah Allah, Yang Maha Esa… dan tidak ada sesuatu pun yang setara dengan-Nya.»"),
"prophets_309": ("Apa sebutan penduduk Makkah untuk Nabi ﷺ sebelum wahyu turun?", ["Al-Amin, yang terpercaya", "Sang musafir", "Sang penyair", "Sang hakim"], "Kejujurannya begitu terkenal sehingga ia dijuluki Al-Amin."),
"prophets_310": ("Siapakah yang disebut Al-Qur'an sebagai teladan terbaik untuk diikuti?", ["Rasulullah ﷺ", "Para raja", "Para penyair", "Para pedagang"], "«Sungguh, telah ada pada diri Rasulullah itu suri teladan yang baik bagimu.»"),
"sira_251": ("Di kota manakah Nabi ﷺ dilahirkan?", ["Makkah", "Madinah", "Yerusalem", "Ta'if"], "Nabi ﷺ lahir di Makkah, dari suku Quraisy."),
"sira_252": ("Ke kota manakah Nabi ﷺ berhijrah?", ["Madinah", "Ta'if", "Kairo", "Damaskus"], "Hijrah berlangsung dari Makkah ke Madinah, yang saat itu bernama Yatsrib."),
"sira_253": ("Apa nama perpindahan dari Makkah ke Madinah?", ["Hijrah", "Haji", "Pembebasan", "Perjanjian"], "Hijrah menandai awal kalender Islam."),
"sira_254": ("Siapakah istri pertama Nabi ﷺ?", ["Khadijah", "Aisyah", "Hafshah", "Saudah"], "Khadijah binti Khuwailid, orang pertama yang beriman kepadanya."),
"sira_255": ("Di gua manakah Nabi ﷺ bersembunyi saat hijrah?", ["Gua Tsur", "Gua Hira", "Gua Uhud", "Gua Quba"], "Beliau bersembunyi di sana selama tiga hari bersama Abu Bakar sebelum melanjutkan perjalanan ke Madinah."),
"sira_256": ("Apa kata pertama yang diwahyukan kepada Nabi ﷺ?", ["«Bacalah»", "«Salatlah»", "«Bangunlah»", "«Dengarlah»"], "«Bacalah dengan nama Tuhanmu yang menciptakan.»"),
"sira_257": ("Malaikat siapakah yang membawa wahyu kepada Nabi ﷺ?", ["Jibril", "Mikail", "Israfil", "Malik"], "Jibril adalah malaikat yang ditugaskan menurunkan wahyu."),
"sira_258": ("Di kota manakah makam Nabi ﷺ berada?", ["Madinah", "Makkah", "Yerusalem", "Ta'if"], "Makam beliau berada di Madinah, di samping masjidnya."),
"sira_259": ("Dari suku manakah Nabi ﷺ berasal?", ["Quraisy", "Aus", "Khazraj", "Tsaqif"], "Nabi ﷺ berasal dari suku Quraisy, suku penduduk Makkah."),
"sira_260": ("Apa sebutan untuk para pengikut yang mendampingi Nabi ﷺ?", ["Para Sahabat", "Para Tabi'in", "Hanya kaum Anshar", "Para Qurra"], "Para Sahabat adalah orang-orang yang melihat Nabi ﷺ dalam keadaan beriman kepadanya."),
"sira_261": ("Siapakah yang menemani Nabi ﷺ saat hijrah?", ["Abu Bakar", "Umar", "Utsman", "Bilal"], "Abu Bakar adalah teman beliau di dalam gua saat hijrah."),
"sira_262": ("Siapakah muazin Nabi ﷺ?", ["Bilal", "Anas", "Zaid", "Salman"], "Bilal bin Rabah mengumandangkan azan di Madinah."),
"sira_263": ("Apa nama perang pertama dalam Islam?", ["Badar", "Uhud", "Khaibar", "Hunain"], "Badar adalah perang besar pertama, pada tahun kedua Hijrah."),
"sira_264": ("Apa sebutan bagi orang-orang yang berhijrah dari Makkah ke Madinah?", ["Kaum Muhajirin", "Kaum Anshar", "Para Tabi'in", "Para sahabat Ta'if"], "Kaum Muhajirin adalah orang-orang yang berhijrah; kaum Anshar adalah orang-orang yang menyambut mereka."),
"sira_265": ("Apa sebutan bagi penduduk Madinah yang menyambut kaum yang berhijrah?", ["Kaum Anshar", "Kaum Muhajirin", "Quraisy", "Para Tabi'in"], "Kaum Anshar, «para penolong», adalah suku Aus dan Khazraj dari Madinah."),
"sira_266": ("Apa yang pertama kali dibangun Nabi ﷺ di Madinah?", ["Masjid", "Pasar", "Istana", "Tembok"], "Beliau membangun masjidnya segera setelah tiba di Madinah."),
"sira_267": ("Putri Nabi ﷺ yang manakah yang menikah dengan Ali?", ["Fathimah", "Ruqayyah", "Zainab", "Ummu Kultsum"], "Fathimah, putri Nabi ﷺ, menikah dengan Ali bin Abi Thalib."),
"sira_268": ("Siapakah khalifah pertama setelah Nabi ﷺ?", ["Abu Bakar", "Umar", "Utsman", "Ali"], "Abu Bakar Ash-Shiddiq adalah khalifah pertama."),
"sira_269": ("Apa nama Madinah sebelumnya?", ["Yatsrib", "Bakkah", "Ta'if", "Khaibar"], "Yatsrib kemudian bernama Madinatun Nabi, kota Nabi ﷺ."),
"sira_270": ("Berapa usia Nabi ﷺ saat menerima wahyu pertama?", ["Empat puluh tahun", "Dua puluh tahun", "Enam puluh tahun", "Tiga puluh tahun"], "Wahyu datang kepada beliau saat berusia empat puluh tahun."),
"sira_271": ("Di kota manakah Ka'bah berada?", ["Makkah", "Madinah", "Yerusalem", "Damaskus"], "Ka'bah berdiri di tengah Masjidil Haram, di Makkah."),
"sira_272": ("Di kota manakah Masjidil Aqsa berada?", ["Yerusalem", "Makkah", "Madinah", "Kairo"], "Masjidil Aqsa berada di Yerusalem (Al-Quds)."),
"sira_273": ("Paman Nabi ﷺ yang manakah yang melindunginya di Makkah?", ["Abu Thalib", "Abu Lahab", "Al-Abbas", "Abu Sufyan"], "Abu Thalib, ayah Ali, melindungi keponakannya dari kaum Quraisy."),
"sira_274": ("Apa pekerjaan Khadijah, istri pertama Nabi ﷺ?", ["Pedagang", "Tabib", "Penyair", "Penenun"], "Khadijah adalah seorang pedagang yang dihormati di Makkah."),
"sira_275": ("Apa nama haji terakhir Nabi ﷺ?", ["Haji Wada' (Haji Perpisahan)", "Haji pertama", "Haji pembebasan", "Haji kecil"], "Haji Wada' berlangsung pada tahun 10 Hijrah."),
"sira_276": ("Apa sebutan untuk kisah hidup Nabi ﷺ?", ["Sirah", "Sunnah", "Tafsir", "Fikih"], "Sirah adalah kisah hidup beliau; Sunnah adalah apa yang beliau ucapkan dan lakukan."),
"sira_277": ("Apa sebutan untuk ucapan yang diriwayatkan dari Nabi ﷺ?", ["Hadis", "Surah", "Ayat", "Doa"], "Hadis adalah ucapan, perbuatan, atau persetujuan Nabi ﷺ."),
"sira_278": ("Dua kitab hadis manakah yang dianggap paling sahih?", ["Sahih al-Bukhari dan Sahih Muslim", "Dua kumpulan puisi", "Dua buku sejarah", "Dua kamus"], "Keduanya bersama-sama disebut «Ash-Shahihain», dua kitab sahih."),
"sira_279": ("Khalifah manakah yang menyalin Al-Qur'an dan mengirimkannya ke berbagai wilayah?", ["Utsman", "Abu Bakar", "Umar", "Ali"], "Utsman memerintahkan pembuatan salinan resmi dan mengirimkannya ke kota-kota utama."),
"sira_280": ("Berapa jumlah «Khulafaur Rasyidin», khalifah yang mendapat petunjuk?", ["Empat", "Dua", "Tujuh", "Dua belas"], "Abu Bakar, Umar, Utsman dan Ali."),
"sira_281": ("Ke arah manakah umat Islam salat?", ["Ke arah Ka'bah, di Makkah", "Ke arah Yerusalem", "Ke arah timur", "Ke arah Madinah"], "Kiblat adalah arah menuju Ka'bah."),
"sira_282": ("Apa sebutan untuk arah salat itu?", ["Kiblat", "Mihrab", "Mimbar", "Menara"], "Kiblat adalah arahnya; mihrab adalah ceruk yang menandainya."),
"sira_283": ("Apa sebutan untuk tempat umat Islam salat berjamaah?", ["Masjid", "Sekolah", "Pasar", "Perpustakaan"], "Masjid adalah tempat bersujud, rumah ibadah umat Islam."),
"sira_284": ("Apa sebutan untuk panggilan salat?", ["Azan", "Takbir", "Tasbih", "Zikir"], "Azan adalah panggilan salat; orang yang mengumandangkannya disebut muazin."),
"sira_285": ("Pada hari apakah umat Islam berkumpul untuk salat besar?", ["Jumat", "Sabtu", "Minggu", "Senin"], "Salat Jumat mengumpulkan umat setiap pekan."),
"sira_286": ("Apa sebutan untuk orang yang memimpin salat?", ["Imam", "Muazin", "Hakim", "Hafiz"], "Imam adalah orang yang jamaah berbaris di belakangnya untuk salat."),
"sira_287": ("Apa sebutan untuk orang yang telah menghafal seluruh Al-Qur'an?", ["Hafiz", "Imam", "Muazin", "Hakim"], "Hafiz adalah orang yang menjaga seluruh Al-Qur'an dalam hafalannya."),
"sira_288": ("Sahabat manakah yang dikenal sebagai perawi hadis terbanyak?", ["Abu Hurairah", "Bilal", "Salman", "Anas"], "Abu Hurairah menghabiskan tahun-tahun terakhir hidup Nabi ﷺ di sisi beliau."),
"sira_289": ("Khalifah manakah yang dijuluki Ash-Shiddiq, «yang membenarkan»?", ["Abu Bakar", "Umar", "Utsman", "Ali"], "Abu Bakar Ash-Shiddiq, laki-laki merdeka pertama yang beriman."),
"sira_290": ("Khalifah manakah yang dijuluki Al-Faruq?", ["Umar bin Khattab", "Abu Bakar", "Utsman", "Ali"], "Umar, yang memisahkan antara yang benar dan yang batil, diberi julukan itu."),
"sira_291": ("Khalifah manakah yang mengumpulkan Al-Qur'an dalam satu mushaf?", ["Abu Bakar", "Muawiyah", "Khalid", "Bilal"], "Abu Bakar memerintahkan agar apa yang telah ditulis dikumpulkan menjadi satu."),
"sira_292": ("Kakek manakah yang mengasuh Nabi ﷺ saat kecil?", ["Abdul Muthalib", "Abu Sufyan", "Al-Walid", "Utbah"], "Kakeknya, Abdul Muthalib, mengasuhnya setelah kelahirannya."),
"sira_293": ("Bagaimana Al-Qur'an mengingatkan masa kecil Nabi ﷺ?", ["Allah mendapatinya sebagai anak yatim lalu melindunginya", "Ia adalah seorang raja", "Ia kaya sejak kecil", "Ia hidup sendirian di gurun"], "«Bukankah Dia mendapatimu sebagai seorang yatim, lalu Dia melindungimu?» (93:6)."),
"sira_294": ("Perang manakah yang terjadi setelah Badar?", ["Uhud", "Khandaq", "Hunain", "Tabuk"], "Pada tahun berikutnya terjadi Perang Uhud, di dekat Madinah."),
"sira_295": ("Apa yang digali kaum Muslimin di sekeliling Madinah untuk mempertahankannya?", ["Parit (Al-Khandaq)", "Sumur", "Terowongan", "Kanal"], "Mereka menggali parit, yang menjadi nama Perang Khandaq (Perang Parit)."),
"sira_296": ("Aisyah, istri Nabi ﷺ, adalah putri siapakah?", ["Abu Bakar", "Umar", "Utsman", "Ali"], "Aisyah adalah putri Abu Bakar Ash-Shiddiq."),
"sira_297": ("Apa sebutan Al-Qur'an untuk istri-istri Nabi ﷺ?", ["Ibu orang-orang beriman", "Para pelayan", "Para teman perjalanan", "Para wanita yang berhijrah"], "«Dan istri-istrinya adalah ibu-ibu mereka» (33:6)."),
"sira_298": ("Sahabat manakah yang menjadi sepupu sekaligus menantu Nabi ﷺ?", ["Ali bin Abi Thalib", "Bilal", "Salman", "Zaid"], "Ali, sepupu Nabi ﷺ, menikah dengan putrinya, Fathimah."),
"sira_299": ("Apa nama masjid Nabi ﷺ di Madinah?", ["Masjid Nabawi", "Masjidil Haram", "Masjidil Aqsa", "Masjid Quba"], "Masjid Nabi ﷺ, Masjid Nabawi, berdiri di Madinah."),
"sira_300": ("Apa nama tunggangan Nabi ﷺ dalam perjalanan malam (Isra)?", ["Al-Buraq", "Al-'Adba'", "Asy-Syaqra'", "Al-Qaswa'"], "Tunggangan dalam perjalanan malam itu bernama Al-Buraq."),
"faith_151": ("Berapa jumlah rukun Islam?", ["Lima", "Tiga", "Enam", "Sepuluh"], "Lima: syahadat, salat, zakat, puasa dan haji."),
"faith_152": ("Apa rukun Islam yang pertama?", ["Syahadat (kesaksian iman)", "Puasa", "Haji", "Zakat"], "Seseorang masuk Islam dengan bersaksi bahwa tidak ada tuhan selain Allah dan Muhammad ﷺ adalah utusan-Nya."),
"faith_153": ("Berapa kali salat wajib yang dikerjakan seorang Muslim setiap hari?", ["Lima", "Tiga", "Tujuh", "Dua"], "Lima salat, tersebar dari fajar hingga malam."),
"faith_154": ("Pada bulan apakah umat Islam berpuasa?", ["Ramadan", "Rajab", "Sya'ban", "Syawal"], "«Bulan Ramadan, bulan yang di dalamnya diturunkan Al-Qur'an» (2:185)."),
"faith_155": ("Apa nama sedekah wajib dalam Islam?", ["Zakat", "Doa", "Zikir", "Tawaf"], "Zakat adalah bagian dari harta yang diberikan setiap tahun."),
"faith_156": ("Apa nama ibadah besar ke Makkah?", ["Haji", "Sa'i", "Zikir", "Sahur"], "Haji adalah ibadah yang dilakukan sekali seumur hidup oleh orang yang mampu."),
"faith_157": ("Berapa jumlah rukun iman (arkanul iman)?", ["Enam", "Empat", "Lima", "Tujuh"], "Iman kepada Allah, para malaikat-Nya, kitab-kitab-Nya, para rasul-Nya, hari Akhir dan takdir."),
"faith_158": ("Berapa jumlah tuhan yang diimani seorang Muslim?", ["Hanya satu", "Dua", "Tiga", "Banyak"], "«Katakanlah: Dialah Allah, Yang Maha Esa» (112:1)."),
"faith_159": ("Apa sebutan umat Islam untuk Tuhan dalam bahasa Arab?", ["Allah", "Malak", "Rasul", "Nabi"], "Allah adalah nama Sang Pencipta dalam bahasa Arab."),
"faith_160": ("Apa nama kitab suci umat Islam?", ["Al-Qur'an", "Taurat", "Injil", "Zabur"], "Al-Qur'an adalah kitab yang diturunkan kepada Nabi Muhammad ﷺ."),
"faith_161": ("Apa nama Rumah Allah yang dibangun di Makkah?", ["Ka'bah", "Raudah", "Maqam", "Hijr"], "«Sesungguhnya rumah (ibadah) pertama yang dibangun untuk manusia ialah yang di Bakkah» (3:96)."),
"faith_162": ("Apa yang diucapkan seorang Muslim sebelum mulai makan?", ["Bismillah", "Amin", "Subhanallah", "Allahumma"], "Nabi ﷺ mengajari seorang anak: «Ucapkanlah Bismillah, dan makanlah dengan tangan kananmu.»"),
"faith_163": ("Bagaimana umat Islam saling memberi salam?", ["Assalamu'alaikum", "Alhamdulillah", "Bismillah", "Allahu akbar"], "«Assalamu'alaikum» berarti: semoga keselamatan tercurah kepadamu."),
"faith_164": ("Apa jawaban untuk «assalamu'alaikum»?", ["Wa'alaikumussalam", "Bismillah", "Amin", "Subhanallah"], "Salam dibalas: «dan semoga keselamatan tercurah kepadamu juga»."),
"faith_165": ("Apa nama hari raya tepat setelah bulan Ramadan?", ["Idulfitri", "Iduladha", "Lailatul Qadar", "Asyura"], "Idulfitri, hari raya berbuka setelah puasa."),
"faith_166": ("Apa nama hari raya kurban?", ["Iduladha", "Idulfitri", "Maulid", "Lailatul Qadar"], "Iduladha jatuh pada hari-hari ibadah haji."),
"faith_167": ("Apa sebutan makhluk Allah yang selalu taat kepada-Nya dan tidak pernah membangkang?", ["Para malaikat", "Para jin", "Para nabi", "Para sahabat"], "Para malaikat melaksanakan apa yang diperintahkan Allah dan tidak pernah membangkang."),
"faith_168": ("Apa sebutan surga dalam bahasa Arab?", ["Al-Jannah", "As-Salat", "Ad-Du'a", "Al-Adzan"], "Al-Jannah, yang secara harfiah berarti «taman», adalah tempat tinggal yang dijanjikan bagi orang-orang beriman."),
"faith_169": ("Apa nama bersuci dengan air yang dilakukan sebelum salat?", ["Wudu", "Tawaf", "Zikir", "Sa'i"], "Wudu adalah bersuci yang dilakukan sebelum salat."),
"faith_170": ("Apa sebutan untuk satu satuan gerakan dalam salat?", ["Rakaat", "Surah", "Azan", "Tawaf"], "Satu rakaat mencakup berdiri, rukuk dan sujud."),
"faith_171": ("Surah manakah yang dibaca pada setiap rakaat salat?", ["Al-Fatihah", "Al-Ikhlas", "An-Nas", "Al-Kautsar"], "Al-Fatihah, surah pembuka, dibaca pada setiap rakaat."),
"faith_172": ("Apa sebutan untuk sesuatu yang dibolehkan dalam Islam?", ["Halal", "Haram", "Sunah", "Fardu"], "Halal berarti sesuatu yang dibolehkan."),
"faith_173": ("Apa sebutan untuk sesuatu yang dilarang dalam Islam?", ["Haram", "Halal", "Mubah", "Nafilah"], "Haram berarti sesuatu yang dilarang."),
"faith_174": ("Daging apakah yang diharamkan Al-Qur'an?", ["Daging babi", "Daging kambing", "Daging sapi", "Daging ayam"], "«Dia telah mengharamkan bagimu bangkai, darah dan daging babi» (2:173)."),
"faith_175": ("Minuman apakah yang diperintahkan Al-Qur'an untuk dijauhi?", ["Khamar dan segala yang memabukkan", "Susu", "Madu", "Air hujan"], "«Khamar, judi… adalah perbuatan keji, maka jauhilah» (5:90)."),
"faith_176": ("Apa yang diucapkan orang yang bersin, sebagaimana diajarkan Nabi ﷺ?", ["Alhamdulillah", "Bismillah", "Allahu akbar", "Amin"], "«Apabila salah seorang di antara kalian bersin, hendaklah ia mengucapkan: alhamdulillah.»"),
"faith_177": ("Bagaimana menyebut «salat» dalam bahasa Arab?", ["Ash-Shalat", "Ash-Shaum", "Az-Zakat", "Al-Hajj"], "Ash-Shalat adalah ibadah salat seorang Muslim."),
"faith_178": ("Apa sebutan untuk memohon sesuatu kepada Allah dengan kata-kata sendiri?", ["Doa", "Tawaf", "Azan", "Sa'i"], "Doa adalah permohonan, memanggil dan memohon kepada Allah."),
"faith_179": ("Apa arti «alhamdulillah»?", ["Segala puji bagi Allah", "Allah Mahabesar", "Dengan nama Allah", "Mahasuci Allah"], "Ini adalah ayat kedua surah Al-Fatihah: «Segala puji bagi Allah, Tuhan seluruh alam» (1:2)."),
"faith_180": ("Apa arti kata «islam»?", ["Berserah diri kepada Allah", "Kekayaan", "Perjalanan", "Ilmu"], "Islam berasal dari akar kata yang berarti berserah diri dan berada dalam kedamaian."),
"faith_181": ("Apa arti kata «muslim»?", ["Orang yang berserah diri kepada Allah", "Orang yang bepergian", "Orang yang mengajar", "Orang yang membangun"], "Muslim adalah orang yang berserah diri hanya kepada Allah."),
"faith_182": ("Siapakah yang menciptakan langit dan bumi, menurut Al-Qur'an?", ["Allah", "Para malaikat", "Para nabi", "Matahari"], "«Segala puji bagi Allah yang telah menciptakan langit dan bumi» (6:1)."),
"faith_183": ("Berapa jumlah nama Allah yang disebutkan dalam hadis?", ["Sembilan puluh sembilan", "Sepuluh", "Lima puluh", "Seribu"], "«Allah memiliki sembilan puluh sembilan nama, seratus kurang satu.»"),
"faith_184": ("Apa yang dilakukan para malaikat yang disebut «para pencatat yang mulia»?", ["Mereka mencatat amal perbuatan kita", "Mereka membawa hujan", "Mereka menjaga Ka'bah", "Mereka mengajarkan bahasa Arab"], "«Para pencatat yang mulia, yang mengetahui apa yang kamu kerjakan» (82:11-12)."),
"faith_185": ("Malam apakah yang digambarkan Al-Qur'an lebih baik daripada seribu bulan?", ["Lailatul Qadar", "Malam Jumat", "Malam hari raya", "Malam pertama Ramadan"], "«Malam kemuliaan itu lebih baik daripada seribu bulan» (97:3)."),
"faith_186": ("Apa sebutan untuk keyakinan bahwa Tuhan hanya satu?", ["Tauhid", "Tawaf", "Tayamum", "Tarawih"], "Tauhid adalah keesaan Allah, inti dari pesan setiap nabi."),
"faith_187": ("Apa sebutan untuk menyekutukan Allah dalam ibadah?", ["Syirik", "Zikir", "Doa", "Sabar"], "Syirik adalah menyekutukan: menyembah sesuatu di samping Allah."),
"faith_188": ("Apa sebutan untuk hari ketika setiap orang akan diadili?", ["Hari Kiamat", "Hari raya", "Hari Jumat", "Hari pertama Ramadan"], "Yaumul Qiyamah, hari Kiamat, hari ketika setiap orang akan melihat amal perbuatannya."),
"faith_189": ("Berapa jumlah bulan dalam setahun menurut Al-Qur'an?", ["Dua belas", "Sepuluh", "Empat belas", "Enam"], "«Sesungguhnya jumlah bulan di sisi Allah ialah dua belas bulan» (9:36)."),
"faith_190": ("Berapa jumlah sujud dalam satu rakaat?", ["Dua", "Satu", "Tiga", "Empat"], "Setiap rakaat mencakup dua kali sujud."),
"quran_151": ("Berapa jumlah surah dalam Al-Qur'an?", ["Seratus empat belas", "Enam puluh", "Dua ratus", "Tiga puluh"], "Al-Qur'an memiliki 114 surah, dari Al-Fatihah hingga An-Nas."),
"quran_152": ("Apa surah pertama dalam Al-Qur'an?", ["Al-Fatihah", "Al-Baqarah", "An-Nas", "Yasin"], "Al-Fatihah, «pembukaan», adalah surah pertama."),
"quran_153": ("Apa arti kata «Qur'an»?", ["Bacaan", "Jalan", "Cahaya", "Taman"], "Qur'an berasal dari akar kata yang berarti membaca dan melafalkan."),
"quran_154": ("Kira-kira berapa lama Al-Qur'an diturunkan?", ["Sekitar dua puluh tiga tahun", "Satu malam", "Seratus tahun", "Tiga tahun"], "Wahyu turun selama kurang lebih dua puluh tiga tahun."),
"quran_155": ("Apa sebutan untuk satu kalimat dalam Al-Qur'an?", ["Ayat", "Surah", "Juz", "Hadis"], "Setiap kalimat bernomor dalam Al-Qur'an disebut ayat, yang berarti «tanda»."),
"quran_156": ("Apa sebutan untuk satu bab dalam Al-Qur'an?", ["Surah", "Ayat", "Juz", "Khutbah"], "Al-Qur'an dibagi menjadi surah-surah, masing-masing dengan namanya sendiri."),
"quran_157": ("Apa surah terpanjang dalam Al-Qur'an?", ["Al-Baqarah", "Al-Fatihah", "Al-Kautsar", "An-Nas"], "Al-Baqarah adalah surah terpanjang dalam Al-Qur'an."),
"quran_158": ("Apa surah terpendek dalam Al-Qur'an?", ["Al-Kautsar", "Al-Baqarah", "Ali 'Imran", "An-Nisa'"], "Al-Kautsar hanya memiliki tiga ayat."),
"quran_159": ("Kalimat apakah yang membuka hampir setiap surah?", ["Dengan nama Allah Yang Maha Pengasih, Maha Penyayang", "Segala puji bagi Allah", "Allah Mahabesar", "Tidak ada tuhan selain Allah"], "Basmalah membuka 113 dari 114 surah."),
"quran_160": ("Firman siapakah Al-Qur'an itu?", ["Firman Allah", "Ucapan Nabi ﷺ", "Ucapan malaikat Jibril", "Ucapan para sahabat"], "Al-Qur'an menyebut dirinya «firman Allah» (kalamullah) dalam ayat 9:6."),
"quran_161": ("Menjadi berapa bagian (juz) Al-Qur'an dibagi?", ["Tiga puluh", "Sepuluh", "Lima puluh", "Seratus"], "Al-Qur'an dibagi menjadi tiga puluh juz, satu untuk setiap malam Ramadan."),
"quran_162": ("Surah manakah yang memakai nama seorang wanita?", ["Maryam", "Yusuf", "Nuh", "Muhammad"], "Surah ke-19 memakai nama Maryam."),
"quran_163": ("Apa sebutan untuk dua surah terakhir yang dibaca untuk memohon perlindungan?", ["Al-Mu'awwidzatain", "Al-Matsani", "Al-Mufashshal", "Al-Hawamim"], "Al-Falaq dan An-Nas disebut Al-Mu'awwidzatain, «dua surah perlindungan»."),
"quran_164": ("Kata apakah yang membuka surah Al-Fatihah, setelah basmalah?", ["Alhamdu", "Qul", "Iqra'", "Inna"], "«Alhamdu lillahi rabbil 'alamin» membuka surah Al-Fatihah."),
"quran_165": ("Apa sebutan untuk penjelasan makna Al-Qur'an?", ["Tafsir", "Tajwid", "Hifz", "Tawaf"], "Tafsir adalah ilmu yang menjelaskan makna ayat-ayat."),
"quran_166": ("Surah manakah yang tidak diawali dengan basmalah?", ["At-Taubah", "Al-Fatihah", "Al-Ikhlas", "An-Nashr"], "At-Taubah adalah satu-satunya surah yang tidak dibuka dengan basmalah."),
"quran_167": ("Apa sebutan untuk orang yang membaca Al-Qur'an dengan suara nyaring?", ["Qari", "Muazin", "Imam", "Khatib"], "Qari adalah pembaca Al-Qur'an."),
"quran_168": ("Dalam surah manakah Ayat Kursi terdapat?", ["Al-Baqarah", "Al-Kahfi", "Yasin", "Al-Mulk"], "Ayat Kursi adalah ayat ke-255 surah Al-Baqarah."),
"quran_169": ("Apa arti «An-Nur», nama surah ke-24?", ["Cahaya", "Malam", "Angin", "Gunung"], "An-Nur berarti «cahaya»."),
"quran_170": ("Surah manakah yang bernama «Yang Maha Pengasih»?", ["Ar-Rahman", "Al-Mulk", "Al-Fath", "Ash-Shaff"], "Surah ke-55 bernama Ar-Rahman."),
"quran_171": ("Surah manakah yang dinamai menurut gua?", ["Al-Kahfi", "Al-Fil", "An-Naml", "Al-Baqarah"], "Al-Kahfi berarti «gua»."),
"quran_172": ("Apa arti «An-Nisa'», nama surah ke-4?", ["Wanita", "Laki-laki", "Anak-anak", "Para musafir"], "An-Nisa' berarti «wanita»."),
"quran_173": ("Apa arti «Al-Ma'idah», nama surah ke-5?", ["Hidangan", "Gunung", "Besi", "Fajar"], "Al-Ma'idah berarti «hidangan»."),
"quran_174": ("Nabi siapakah yang namanya menjadi nama surah ke-71?", ["Nuh", "Hud", "Yunus", "Ibrahim"], "Surah ke-71 bernama Nuh."),
"quran_175": ("Berapa jumlah ayat surah Al-Fatihah?", ["Tujuh", "Tiga", "Sepuluh", "Dua puluh"], "Al-Fatihah memiliki tujuh ayat."),
"quran_176": ("Di manakah Al-Qur'an menyatakan dirinya terpelihara?", ["Di Lauh Mahfuz", "Di dalam gua", "Di dalam peti", "Di atas gunung"], "«Bahkan yang didustakan mereka itu ialah Al-Qur'an yang mulia, yang tersimpan dalam Lauh Mahfuz» (85:21-22)."),
"quran_177": ("Surah manakah yang dinamai menurut bulan?", ["Al-Qamar", "Asy-Syams", "An-Najm", "Al-Lail"], "Al-Qamar berarti «bulan»."),
"quran_178": ("Surah manakah yang dinamai menurut hari Kiamat?", ["Al-Qiyamah", "Al-Fath", "Al-Hasyr", "Ash-Shaff"], "Surah ke-75 bernama Al-Qiyamah."),
"quran_179": ("Nabi siapakah yang namanya menjadi nama surah ke-14?", ["Ibrahim", "Muhammad ﷺ", "Yusuf", "Hud"], "Surah ke-14 bernama Ibrahim."),
"quran_180": ("Apa arti «Al-Hadid», nama surah ke-57?", ["Besi", "Emas", "Kayu", "Batu"], "Al-Hadid berarti «besi»."),
"virtues_101": ("Bagaimana Al-Qur'an mengajarkan kita berbicara kepada orang tua?", ["Dengan perkataan yang mulia, bahkan tidak mengucapkan «ah»", "Lebih keras daripada mereka", "Dengan selalu diam", "Hanya pada hari Jumat"], "«Janganlah engkau mengatakan kepada keduanya perkataan «ah», dan ucapkanlah kepada keduanya perkataan yang baik» (17:23)."),
"virtues_102": ("Apa sebutan untuk pemberian sukarela yang diberikan karena kebaikan hati?", ["Sedekah", "Zakat", "Tawaf", "Azan"], "Sedekah adalah pemberian sukarela, kecil maupun besar."),
"virtues_103": ("Apa nasihat Nabi ﷺ tentang ucapan, bagi siapa yang beriman kepada Allah dan hari Akhir?", ["Hendaklah ia berkata baik atau diam", "Hendaklah ia banyak bicara", "Hendaklah ia tidak pernah bicara", "Hendaklah ia berbicara hanya kepada keluarganya"], "«Barang siapa beriman kepada Allah dan hari Akhir, hendaklah ia berkata baik atau diam.»"),
"virtues_104": ("Bagaimana Nabi ﷺ mengajarkan kita memperlakukan tetangga?", ["Berbuat baik kepadanya", "Menjauhinya", "Tidak pernah berbicara dengannya", "Memintanya pergi"], "«Barang siapa beriman kepada Allah dan hari Akhir, hendaklah ia memuliakan tetangganya.»"),
"virtues_105": ("Allah bersama siapakah, menurut Al-Qur'an?", ["Bersama orang-orang yang sabar", "Bersama orang-orang terkaya", "Bersama orang-orang terkuat", "Bersama orang-orang tercepat"], "«Sesungguhnya Allah bersama orang-orang yang sabar» (2:153)."),
"virtues_106": ("Apa yang dilarang Al-Qur'an untuk dilakukan terhadap anak yatim?", ["Berlaku sewenang-wenang kepadanya", "Mengajarinya membaca", "Mengajaknya makan", "Bermain dengannya"], "«Maka terhadap anak yatim, janganlah engkau berlaku sewenang-wenang» (93:9)."),
"virtues_107": ("Ucapan seperti apakah yang diperintahkan Al-Qur'an untuk dijauhi?", ["Perkataan dusta", "Perkataan lembut", "Ucapan terima kasih", "Ucapan salam"], "«Dan jauhilah perkataan dusta» (22:30)."),
"virtues_108": ("Selain kerabat dekat, kepada siapakah Al-Qur'an memerintahkan kita memberikan haknya?", ["Orang miskin dan orang dalam perjalanan", "Raja dan hakim", "Pedagang", "Penyair"], "«Dan berikanlah haknya kepada kerabat dekat, juga kepada orang miskin dan orang yang dalam perjalanan» (17:26)."),
"virtues_109": ("Apa yang dijanjikan Allah bagi orang yang bersyukur kepada-Nya?", ["Menambahkan nikmat baginya", "Membuatnya bepergian", "Membuatnya terkenal", "Menjadikannya raja"], "«Jika kamu bersyukur, niscaya Aku akan menambah nikmat kepadamu» (14:7)."),
"virtues_110": ("Bagaimana menyebut «kesabaran» dalam bahasa Arab?", ["Ash-Shabr", "Asy-Syukr", "Ash-Shidq", "Al-Haya'"], "Ash-Shabr adalah keteguhan dalam kesulitan dan dalam ketaatan."),
"faith_191": ("Apa sebutan untuk mengingat Allah dengan mengulang pujian kepada-Nya?", ["Zikir", "Haji", "Sa'i", "Tayamum"], "Zikir adalah mengingat Allah dengan lisan dan hati."),
"faith_192": ("Apa bulan pertama dalam tahun Islam?", ["Muharram", "Ramadan", "Syawal", "Rajab"], "Tahun Hijriah dibuka dengan bulan Muharram."),
"faith_193": ("Apa sebutan untuk kembali kepada Allah setelah berbuat dosa?", ["Tobat", "Tawaf", "Tajwid", "Tarawih"], "Tobat adalah penyesalan: menyesal, berhenti, dan kembali kepada Allah."),
"faith_194": ("Siapakah yang memberi rezeki kepada setiap makhluk di bumi?", ["Allah", "Para raja", "Para pedagang", "Para malaikat"], "«Tidak ada satu pun makhluk bergerak di bumi melainkan dijamin Allah rezekinya» (11:6)."),
"faith_195": ("Di kota manakah ibadah haji dilaksanakan?", ["Di Makkah", "Di Madinah", "Di Yerusalem", "Di Kairo"], "Haji dilaksanakan di Makkah dan tempat-tempat sucinya."),
"faith_196": ("Apa sebutan untuk orang yang sedang menunaikan ibadah haji?", ["Jamaah haji (hajji)", "Imam", "Qari", "Muazin"], "Orang yang menunaikan haji disebut hajji."),
"faith_197": ("Apa yang diketahui Allah, menurut Al-Qur'an, meskipun tersembunyi?", ["Apa yang ada di dalam hati", "Hanya perbuatan yang terlihat", "Hanya kata-kata yang diucapkan", "Tidak ada yang tersembunyi"], "«Jika kamu sembunyikan apa yang ada dalam hatimu atau kamu tampakkan, Allah mengetahuinya» (3:29)."),
"faith_198": ("Kepada siapakah puasa diwajibkan, menurut Al-Qur'an?", ["Kepada orang-orang beriman, sebagaimana kepada orang-orang sebelum mereka", "Hanya kepada para musafir", "Hanya kepada para ulama", "Hanya kepada anak-anak"], "«Wahai orang-orang yang beriman, diwajibkan atas kamu berpuasa sebagaimana diwajibkan atas orang-orang sebelum kamu» (2:183)."),
"faith_199": ("Apa nama salat berjamaah besar pada hari Jumat?", ["Salat Jumat", "Salat Id", "Salat Witir", "Salat Duha"], "Salat Jumat mengumpulkan kaum Muslimin pada tengah hari Jumat."),
"faith_200": ("Bagaimana menyebut «puasa» dalam bahasa Arab?", ["Ash-Shaum", "Ash-Shalat", "Az-Zakat", "Al-Adzan"], "Ash-Shaum adalah puasa, rukun Islam yang keempat."),
}
